const D = { crinkle: .55, amp: .6, density: .6, speed: 1, hue: 210, energy: .7, scale: 1, x: .5, y: .72, style: 'spectral', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const MAXOCT = 11, MAXBANDS = 13;
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.ph = []; S.shiv = [];
  for (let n = 0; n < MAXOCT; n++) { S.ph[n] = fr(n + 3) * 1000; S.shiv[n] = (fr(n + 40) - .5) * 0.9 * (1 + n * 0.15); }
  S.hj = []; S.scj = []; S.bj = []; S.dir = [];
  for (let b = 0; b < MAXBANDS; b++) { S.hj[b] = (fr(b + 70) - .5) * 22; S.scj[b] = 0.6 + fr(b + 100) * 0.9; S.bj[b] = (fr(b + 130) - .5) * 0.5; S.dir[b] = fr(b + 160) < 0.5 ? -1 : 1; }
}

const t = K.t;
const aAll = P.alpha / 100;
const u = Math.min(width, height);
const NB = 3 + Math.round(P.density * (MAXBANDS - 3));
const sec = K.section | 0;
const secDrift = Math.sin(sec * 0.9) * 30 + t * 2.0;
const hueSpread = 120 + K.intensity * 70;
const rough = 0.5 + P.crinkle * 0.12;
const maxOct = 2 + Math.round(P.crinkle * 7);
const swell = 1 + K.swell * 0.15 + A.rms * 0.5;
const baseY = P.y * height;
const spanBase = 1.1 + P.scale * 1.3;
const style = P.style;

function tri(v) { const f = v - Math.floor(v); return f < .5 ? f * 2 : (1 - f) * 2; }
function blanc(xx, dep) {
  let sum = 0, w = 1, tot = 0;
  for (let n = 0; n <= dep; n++) {
    const p = S.ph[n] + t * S.shiv[n] * P.speed * 0.15 + A.bass * 0.4;
    sum += w * tri(Math.pow(2, n) * xx + p);
    tot += w; w *= rough;
  }
  return sum / tot;
}
function thermal(m) { m = Math.max(0, Math.min(1, m)); return [5 + m * 50, 100 - m * 78, 18 + m * 78]; }

// dark spectral ground so the frame is never near-black and never empty
push();
noStroke();
const bgH = ((P.hue + secDrift + 200) % 360 + 360) % 360;
fill(bgH, 42, 8 + P.energy * 5, 100 * aAll);
rect(0, 0, width, height);
pop();

if (style === 'aurora') blendMode(ADD);

for (let b = 0; b < NB; b++) {
  const bf = NB > 1 ? b / (NB - 1) : 0;                 // 0 back .. 1 front
  const freqBand = 0.6 + bf * 1.4;
  const unitsAcross = spanBase * freqBand;
  let depth = Math.round(maxOct * (0.4 + 0.6 * bf));
  depth = Math.max(1, Math.min(MAXOCT - 1, depth));
  const samples = Math.min(360, 70 + depth * 46);
  let cap = Math.floor(Math.log2(Math.max(2, (samples / 2.3) / unitsAcross)));
  cap = Math.max(1, cap);
  const dep = Math.min(depth, cap);
  const ampPix = P.amp * u * (0.12 + 0.44 * bf) * swell;
  const baselineY = baseY - (1 - bf) * (height * 0.46) + S.bj[b] * height * 0.05;
  const scrollX = t * P.speed * (0.05 + bf * 0.16) * S.scj[b] * S.dir[b] + P.x * 0.6;

  // build silhouette
  const xs = [], ys = [];
  for (let i = 0; i <= samples; i++) {
    const x01 = i / samples;
    const val = blanc(x01 * unitsAcross + scrollX, dep);
    xs.push(x01 * width);
    ys.push(baselineY - val * ampPix);
  }

  const hh = ((P.hue + bf * hueSpread + secDrift + S.hj[b]) % 360 + 360) % 360;

  if (style === 'ink') {
    // ink-crease: monochrome contour lines only, no mass — abstracted
    noFill();
    const g = 40 + bf * 55;
    stroke(bgH, 6, g, (55 + P.energy * 35) * aAll);
    strokeWeight(0.6 + bf * 1.8);
    beginShape();
    for (let i = 0; i <= samples; i++) vertex(xs[i], ys[i]);
    endShape();
  } else if (style === 'neon') {
    // dark mass + glowing crest wire
    noStroke();
    fill(hh, 60, 10 + bf * 8, (55 + P.energy * 25) * aAll);
    beginShape();
    for (let i = 0; i <= samples; i++) vertex(xs[i], ys[i]);
    vertex(width, height); vertex(0, height);
    endShape(CLOSE);
    blendMode(ADD);
    noFill();
    stroke(hh, 80, 100, (40 + P.energy * 40) * aAll);
    strokeWeight(1 + bf * 1.4);
    drawingContext.shadowBlur = 12 + bf * 10;
    drawingContext.shadowColor = color(hh, 90, 100).toString();
    beginShape();
    for (let i = 0; i <= samples; i++) vertex(xs[i], ys[i]);
    endShape();
    drawingContext.shadowBlur = 0;
    blendMode(BLEND);
  } else if (style === 'thermal') {
    const c = thermal(0.15 + bf * 0.8);
    noStroke();
    fill(c[0], c[1], c[2], (40 + P.energy * 30) * aAll);
    beginShape();
    for (let i = 0; i <= samples; i++) vertex(xs[i], ys[i]);
    vertex(width, height); vertex(0, height);
    endShape(CLOSE);
  } else if (style === 'aurora') {
    // luminous ADD curtains: low-alpha glow mass + bright crest
    noStroke();
    fill(hh, 55, 45 + bf * 30, (10 + P.energy * 12) * aAll);
    beginShape();
    for (let i = 0; i <= samples; i++) vertex(xs[i], ys[i]);
    vertex(width, height); vertex(0, height);
    endShape(CLOSE);
    noFill();
    stroke((hh + 20) % 360, 45, 100, (30 + P.energy * 30) * aAll);
    strokeWeight(1 + bf * 1.6);
    beginShape();
    for (let i = 0; i <= samples; i++) vertex(xs[i], ys[i]);
    endShape();
  } else {
    // spectral-fabric (default): stacked translucent spectral bands
    noStroke();
    fill(hh, 72 - bf * 16, 52 + bf * 40, (30 + P.energy * 28) * aAll);
    beginShape();
    for (let i = 0; i <= samples; i++) vertex(xs[i], ys[i]);
    vertex(width, height); vertex(0, height);
    endShape(CLOSE);
    // thin crest highlight for crease definition
    noFill();
    stroke(hh, 40, 92, (18 + P.energy * 20) * aAll);
    strokeWeight(0.8 + bf * 0.8);
    beginShape();
    for (let i = 0; i <= samples; i++) vertex(xs[i], ys[i]);
    endShape();
  }
}

if (style === 'aurora') blendMode(BLEND);

// audio sparkle on treble, partial (never full-frame flash)
if ((A.treble > 0.02 || A.rms > 0.02)) {
  push();
  blendMode(ADD);
  noStroke();
  const gl = (A.treble * 0.6 + A.rms * 0.4) * P.energy;
  fill(((P.hue + 40) % 360 + 360) % 360, 30, 100, gl * 18 * aAll);
  rect(0, baseY - u * 0.3, width, u * 0.6);
  blendMode(BLEND);
  pop();
}
